def factorize(n):
    factors = defaultdict(int)
    # Check for 2 separately
    while n % 2 == 0:
        factors[2] += 1
        n //= 2
    # Now n is odd
    f = 3
    while f * f <= n:
        if n % f == 0:
            factors[f] += 1
            n //= f
        else:
            f += 2
    if n > 1:
        factors[n] += 1
    return factors

