class Solution:
    def subarraySum(self, nums: List[int]) -> int:
        total_sum = 0
        n = len(nums)
        for i in range(n):
            start = max(0, i - nums[i])
            current_sum = 0
            for j in range(start, i + 1):
                current_sum += nums[j]
            total_sum += current_sum
        return total_sum

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        m = len(grid)
        n = len(grid[0])
        result = []
        for i in range(m):
            if i % 2 == 0:
                for j in range(n):
                    if (i+j) % 2 == 0:
                        result.append(grid[i][j])
            else:
                for j in range(n-1, -1, -1):
                    if (i+j) % 2 == 0:
                        result.append(grid[i][j])
        return result

